public class Main {
    int subarraySum(int[] nums, int k) {
        int count = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {                             // every possible starting index
            int runningSum = 0;
            for (int j = i; j < n; j++) {                           // extend the subarray one step at a time
                runningSum += nums[j];
                if (runningSum == k) count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        int k = 3;
        Main solution = new Main();
        System.out.println(solution.subarraySum(nums, k));
    }
}

