import java.util.*;

public class Main {
    int subarraySum(int[] nums, int k) {
        int count = 0;
        int prefixSum = 0;
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);                                            // an empty prefix (sum 0) has occurred once
        for (int num : nums) {
            prefixSum += num;
            count += seen.getOrDefault(prefixSum - k, 0);              // how many earlier prefixes complete a sum of k
            seen.put(prefixSum, seen.getOrDefault(prefixSum, 0) + 1);
        }
        return count;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        int k = 3;
        Main solution = new Main();
        System.out.println(solution.subarraySum(nums, k));
    }
}

