#include <bits/stdc++.h>
using namespace std;

int subarraySum(vector<int>& nums, int k) {
    int count = 0;
    int prefixSum = 0;
    unordered_map<int, int> seen;
    seen[0] = 1;                                                // an empty prefix (sum 0) has occurred once
    for (int num : nums) {
        prefixSum += num;
        auto it = seen.find(prefixSum - k);
        if (it != seen.end()) count += it->second;                  // how many earlier prefixes complete a sum of k
        seen[prefixSum]++;
    }
    return count;
}

int main() {
    vector<int> nums = {1, 2, 3};
    int k = 3;
    cout << subarraySum(nums, k) << endl;
    return 0;
}
